<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Người thuê</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><link rel="stylesheet" href="/assets/css/style.css"><style>.tenant-portrait{width:90px;height:120px;object-fit:cover;border-radius:10px;border:2px solid #dbeafe;background:#f8fafc}.document-photo{width:100%;height:158px;object-fit:cover;border:1px solid #cbd5e1;border-radius:10px}.document-item{min-width:160px;max-width:220px}.detail-label{font-size:.76rem;text-transform:uppercase;letter-spacing:.04em;color:#64748b}.tenant-action{width:34px;height:34px;display:inline-grid;place-items:center}.tenant-action svg{width:17px;height:17px;fill:currentColor}.modal-tenant-info .modal-dialog{max-width:920px}</style></head>
<body><div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-badge"><img src="/assets/pics/logo.webp" class="brand-logo" alt="Logo"></div><div><div class="brand-title">Trọ Tốt</div><div class="brand-subtitle">Management System</div></div></div><div class="user-mini sidebar-top"><img src="<?=htmlspecialchars(getAvatarUrl($user))?>" class="avatar-img" alt="avatar"><div class="user-info"><strong><?=htmlspecialchars($user['HoTen'])?></strong><small><?=htmlspecialchars($user['VaiTro'])?></small></div><a href="/logout.php" class="logout-btn" aria-label="Đăng xuất"><i class="bi bi-box-arrow-right"></i></a></div><nav class="nav-menu"><a class="nav-item" href="/index.php"><i class="bi bi-speedometer2"></i> Dashboard</a><a class="nav-item" href="/views/khu/index.php"><i class="bi bi-buildings"></i> Quản lý phòng thuê</a><a class="nav-item active" href="/views/nguoithue/index.php"><i class="bi bi-people"></i> Người thuê</a><a class="nav-item" href="/views/hopdong/index.php"><i class="bi bi-file-earmark-text"></i> Hợp đồng</a><a class="nav-item" href="/views/chisodiennuoc/index.php"><i class="bi bi-lightning-charge"></i> Điện / Nước</a><a class="nav-item" href="/views/hoadon/index.php"><i class="bi bi-receipt"></i> Hóa đơn</a><a class="nav-item" href="/views/tamtru/index.php"><i class="bi bi-person-vcard"></i> Tạm trú / Lưu trú</a><a class="nav-item" href="/views/baocao/index.php"><i class="bi bi-bar-chart"></i> Báo cáo</a></nav></aside><main class="main-panel" data-page-title="Người thuê"><header class="topbar"><div><h2>Người thuê</h2><p>Tra cứu hồ sơ, giấy tờ định danh, phòng và hợp đồng đang hiệu lực.</p></div></header><section class="card-panel"><div class="d-flex gap-2 align-items-center mb-3"><i class="bi bi-search text-muted"></i><input id="tenantSearch" class="form-control" placeholder="Tìm theo họ tên, CCCD, số điện thoại hoặc phòng"></div><div class="table-responsive"><table class="table table-modern"><thead><tr><th>Người thuê</th><th>CCCD</th><th>Phòng hiện tại</th><th>Liên hệ</th><th class="text-end">Chi tiết</th></tr></thead><tbody id="tenantRows"><tr><td colspan="5" class="text-muted text-center py-4">Đang tải dữ liệu…</td></tr></tbody></table></div></section></main></div>
<div class="modal fade modal-tenant-info" id="tenantDetailModal" tabindex="-1"><div class="modal-dialog modal-dialog-scrollable modal-dialog-centered"><div class="modal-content"><div class="modal-header"><h5 class="modal-title" id="tenantDetailTitle">Hồ sơ người thuê</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body" id="tenantDetailContent"></div><div class="modal-footer"><button class="btn btn-light" data-bs-dismiss="modal">Đóng</button></div></div></div></div>
<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script src="/assets/js/app.js"></script><script>(()=>{const body=document.getElementById('tenantRows'),search=document.getElementById('tenantSearch'),modal=bootstrap.Modal.getOrCreateInstance(document.getElementById('tenantDetailModal'));let rows=[];const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=x=>new Intl.NumberFormat('en-US').format(Number(x||0))+' ₫';const date=x=>x?String(x).replace(/(\d{4})-(\d{2})-(\d{2}).*/,'$3/$2/$1'):'—';const image=(src,label)=>src?`<a class="document-item text-decoration-none" href="${esc(src)}" target="_blank" rel="noopener"><img class="document-photo" src="${esc(src)}" alt="${esc(label)}"><small class="d-block mt-1 text-center">${esc(label)}</small></a>`:`<div class="document-item"><div class="document-photo d-grid place-items-center text-muted small text-center p-2">Chưa có ${esc(label)}</div><small class="d-block mt-1 text-center">${esc(label)}</small></div>`;function render(){const q=search.value.trim().toLowerCase();const list=rows.filter(x=>[x.HoTen,x.CCCD,x.SoDienThoai,x.SoPhong,x.TenDay,x.TenKhu].join(' ').toLowerCase().includes(q));body.innerHTML=list.map((x,i)=>`<tr><td><div class="d-flex align-items-center gap-2">${x.AnhChanDung?`<img src="${esc(x.AnhChanDung)}" style="width:40px;height:52px;object-fit:cover;border-radius:6px" alt="">`:'<i class="bi bi-person-circle fs-3 text-secondary"></i>'}<div><strong>${esc(x.HoTen)}</strong><br><small class="text-muted">${x.LoaiThanhVien==='NguoiKyHopDong'?'Người ký hợp đồng':(x.LoaiThanhVien==='LuuTru'?'Người lưu trú':'Thành viên phòng')}</small></div></div></td><td>${esc(x.CCCD)}</td><td>${esc(x.TenKhu)} · ${esc(x.TenDay)}<br><strong>Phòng ${esc(x.SoPhong)}</strong></td><td>${esc(x.SoDienThoai)}<br><small>${esc(x.Email)}</small></td><td class="text-end"><button class="btn btn-outline-primary tenant-action view-tenant" data-index="${i}" title="Xem hồ sơ" aria-label="Xem hồ sơ"><svg viewBox="0 0 16 16"><path d="M8 3C4.3 3 1.5 5.4.5 8c1 2.6 3.8 5 7.5 5s6.5-2.4 7.5-5C14.5 5.4 11.7 3 8 3Zm0 8.2A3.2 3.2 0 1 1 8 4.8a3.2 3.2 0 0 1 0 6.4Zm0-1.5A1.7 1.7 0 1 0 8 6.3a1.7 1.7 0 0 0 0 3.4Z"></path></svg></button></td></tr>`).join('')||'<tr><td colspan="5" class="text-center text-muted py-4">Không tìm thấy người thuê phù hợp.</td></tr>'}function open(x){document.getElementById('tenantDetailTitle').textContent='Hồ sơ: '+(x.HoTen||'Người thuê');document.getElementById('tenantDetailContent').innerHTML=`<div class="row g-4"><div class="col-md-auto text-center">${x.AnhChanDung?`<img class="tenant-portrait" src="${esc(x.AnhChanDung)}" alt="Ảnh chân dung">`:'<div class="tenant-portrait d-grid place-items-center text-muted"><i class="bi bi-person fs-1"></i></div>'}<div class="small text-muted mt-1">Ảnh chân dung 3×4</div></div><div class="col"><h5 class="mb-3">${esc(x.HoTen)}</h5><div class="row g-3"><div class="col-sm-6"><div class="detail-label">CCCD</div>${esc(x.CCCD)}</div><div class="col-sm-6"><div class="detail-label">Ngày sinh / giới tính</div>${date(x.NgaySinh)} · ${esc(x.GioiTinh||'—')}</div><div class="col-sm-6"><div class="detail-label">Số điện thoại</div>${esc(x.SoDienThoai||'—')}</div><div class="col-sm-6"><div class="detail-label">Email</div>${esc(x.Email||'—')}</div><div class="col-12"><div class="detail-label">Địa chỉ thường trú</div>${esc(x.DiaChiThuongTru||'—')}</div><div class="col-12"><div class="detail-label">Nghề nghiệp</div>${esc(x.NgheNghiep||'—')}</div></div></div></div><hr><h6>Giấy tờ định danh</h6><div class="d-flex gap-3 flex-wrap">${image(x.AnhCCCDMatTruoc,'CCCD mặt trước')}${image(x.AnhCCCDMatSau,'CCCD mặt sau')}${image(x.VNeIDMuc2,'VNeID mức 2')}</div><hr><h6>Thông tin thuê phòng</h6><div class="row g-3"><div class="col-md-4"><div class="detail-label">Khu / dãy / phòng</div>${esc(x.TenKhu)}<br>${esc(x.TenDay)} · <strong>Phòng ${esc(x.SoPhong)}</strong></div><div class="col-md-4"><div class="detail-label">Vai trò trong phòng</div>${x.LoaiThanhVien==='NguoiKyHopDong'?'Người ký hợp đồng':(x.LoaiThanhVien==='LuuTru'?'Người lưu trú':'Thành viên phòng')}</div><div class="col-md-4"><div class="detail-label">Trạng thái hợp đồng</div>${esc(x.TrangThaiHopDong||'—')}</div></div><hr><h6>Hợp đồng</h6>${x.HopDongId?`<div class="border rounded-3 p-3 d-flex justify-content-between align-items-center gap-3"><div><strong>${esc(x.SoHopDong||('Hợp đồng #'+x.HopDongId))}</strong><br><small>${date(x.NgayBatDau)} → ${date(x.NgayKetThuc)} · Giá thuê ${money(x.GiaThue)} · Cọc ${money(x.TienCoc)}</small></div><a class="btn btn-outline-primary" target="_blank" href="/views/hopdong/xem.php?id=${Number(x.HopDongId)}"><i class="bi bi-file-earmark-text"></i> Xem hợp đồng</a></div>`:'<p class="text-muted mb-0">Chưa có hợp đồng hiệu lực.</p>'}`;modal.show()}document.addEventListener('click',e=>{const b=e.target.closest('.view-tenant');if(b)open(rows[Number(b.dataset.index)])});search.addEventListener('input',render);window.app.api('/api/nguoithue.php').then(r=>{rows=r.data||[];render()}).catch(()=>{body.innerHTML='<tr><td colspan="5" class="text-danger text-center py-4">Không thể tải danh sách người thuê.</td></tr>'})})();</script></body></html>
